import React, { useState, useMemo } from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts";

// --- Tipos ---
type Fila = Record<string, any>;
type Datos = {
  [alias: string]: {
    columnas: { clave: string; titulo: string; tipo: string }[];
    filas: Fila[];
    periodo?: string | null;
  };
};
type Accion = {
  tipo: "precios";
  cambios: { productId: string; precio: number }[];
  motivo: string;
};

// --- Utilidades ---
const formatBs = (num: number | null | undefined) => {
  if (num === null || num === undefined) return "Sin dato";
  return "Bs " + num.toLocaleString("es-BO", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

const formatPct = (num: number | null | undefined) => {
  if (num === null || num === undefined) return "Sin dato";
  return num.toLocaleString("es-BO", { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + " %";
};

export default function Herramienta({
  datos,
  proponer,
}: {
  datos: Datos;
  proponer: (accion: Accion) => void;
}) {
  const dataset = datos.precios_bebidas;
  const filas = dataset?.filas || [];

  // --- Estados (Controles de Simulación) ---
  const [aumentoPct, setAumentoPct] = useState<number>(10);
  const [caidaVentasPct, setCaidaVentasPct] = useState<number>(5);

  // --- Cálculos ---
  const { metricas, productosProcesados, faltanCostos } = useMemo(() => {
    let ingresoActualTotal = 0;
    let ingresoProyectadoTotal = 0;
    let gananciaActualTotal = 0;
    let gananciaProyectadaTotal = 0;
    let faltanCostos = false;

    const procesados = filas.map((fila) => {
      const precio = Number(fila._precio || fila.precio || 0);
      const costo = fila._costo !== null && fila._costo !== undefined ? Number(fila._costo) : null;
      const vendidas = Number(fila.vendidas30 || 0);

      if (costo === null) faltanCostos = true;

      // Proyecciones
      const nuevoPrecio = precio * (1 + aumentoPct / 100);
      const nuevasVentas = vendidas * (1 - caidaVentasPct / 100);

      const ingresoActual = precio * vendidas;
      const ingresoProyectado = nuevoPrecio * nuevasVentas;

      const gananciaActual = costo !== null ? (precio - costo) * vendidas : 0;
      const gananciaProyectada = costo !== null ? (nuevoPrecio - costo) * nuevasVentas : 0;

      ingresoActualTotal += ingresoActual;
      ingresoProyectadoTotal += ingresoProyectado;
      gananciaActualTotal += gananciaActual;
      gananciaProyectadaTotal += gananciaProyectada;

      return {
        ...fila,
        precioActual: precio,
        nuevoPrecio,
        vendidasActual: vendidas,
        vendidasProyectadas: nuevasVentas,
        ingresoActual,
        ingresoProyectado,
        gananciaActual,
        gananciaProyectada,
        costo,
      };
    });

    // Ordenar para el gráfico (top 5 por ingresos proyectados)
    const topProductos = [...procesados]
      .sort((a, b) => b.ingresoProyectado - a.ingresoProyectado)
      .slice(0, 5);

    return {
      metricas: {
        ingresoActualTotal,
        ingresoProyectadoTotal,
        gananciaActualTotal,
        gananciaProyectadaTotal,
        difIngreso: ingresoProyectadoTotal - ingresoActualTotal,
        difGanancia: gananciaProyectadaTotal - gananciaActualTotal,
      },
      productosProcesados: procesados,
      topProductos,
      faltanCostos,
    };
  }, [filas, aumentoPct, caidaVentasPct]);

  // --- Acciones ---
  const aplicarPrecios = () => {
    const cambios = productosProcesados
      .filter((p) => p._productId && p.nuevoPrecio > 0)
      .map((p) => ({
        productId: p._productId,
        precio: Number(p.nuevoPrecio.toFixed(2)),
      }));

    if (cambios.length > 0) {
      proponer({
        tipo: "precios",
        cambios,
        motivo: `Aumento general del ${aumentoPct}% en bebidas, asumiendo caída de ventas del ${caidaVentasPct}%.`,
      });
    }
  };

  // --- Renderizados ---
  if (filas.length === 0) {
    return (
      <div className="p-4 rounded-xl border border-border bg-card text-center">
        <p className="text-muted-foreground">
          No se encontraron bebidas para simular. Revisá que haya productos en esta categoría.
        </p>
      </div>
    );
  }

  return (
    <div className="grid gap-4 w-full max-w-full">
      {/* Controles */}
      <div className="rounded-xl border border-border bg-card p-4 grid gap-4 sm:grid-cols-2">
        <div>
          <label className="block text-sm font-semibold text-foreground mb-2">
            1. ¿Cuánto querés subir los precios? ({aumentoPct}%)
          </label>
          <input
            type="range"
            min="0"
            max="50"
            step="1"
            value={aumentoPct}
            onChange={(e) => setAumentoPct(Number(e.target.value))}
            className="w-full accent-primary"
          />
          <p className="text-xs text-muted-foreground mt-1">
            Aplica a todas las bebidas de la lista.
          </p>
        </div>
        <div>
          <label className="block text-sm font-semibold text-foreground mb-2">
            2. ¿Cuánto creés que bajen las ventas? ({caidaVentasPct}%)
          </label>
          <input
            type="range"
            min="0"
            max="50"
            step="1"
            value={caidaVentasPct}
            onChange={(e) => setCaidaVentasPct(Number(e.target.value))}
            className="w-full accent-primary"
          />
          <p className="text-xs text-muted-foreground mt-1">
            Si sube el precio, es normal vender un poco menos.
          </p>
        </div>
      </div>

      {/* Resumen de Impacto */}
      <div className="grid gap-3 sm:grid-cols-2">
        <div className="rounded-xl border border-border bg-card p-4">
          <h3 className="text-sm font-semibold text-muted-foreground mb-1">
            Ingresos Estimados (30 días)
          </h3>
          <div className="flex items-baseline gap-2">
            <span className="text-2xl font-semibold text-foreground">
              {formatBs(metricas.ingresoProyectadoTotal)}
            </span>
          </div>
          <p className="text-sm mt-1">
            Actual: {formatBs(metricas.ingresoActualTotal)}
            <span
              className={`ml-2 font-medium ${
                metricas.difIngreso >= 0 ? "text-success" : "text-destructive"
              }`}
            >
              ({metricas.difIngreso >= 0 ? "+" : ""}
              {formatBs(metricas.difIngreso)})
            </span>
          </p>
        </div>

        <div className="rounded-xl border border-border bg-card p-4">
          <h3 className="text-sm font-semibold text-muted-foreground mb-1">
            Ganancia Estimada (30 días)
          </h3>
          <div className="flex items-baseline gap-2">
            <span className="text-2xl font-semibold text-foreground">
              {formatBs(metricas.gananciaProyectadaTotal)}
            </span>
          </div>
          <p className="text-sm mt-1">
            Actual: {formatBs(metricas.gananciaActualTotal)}
            <span
              className={`ml-2 font-medium ${
                metricas.difGanancia >= 0 ? "text-success" : "text-destructive"
              }`}
            >
              ({metricas.difGanancia >= 0 ? "+" : ""}
              {formatBs(metricas.difGanancia)})
            </span>
          </p>
          {faltanCostos && (
            <p className="text-xs text-warning mt-1">
              * Algunos productos no tienen costo, la ganancia real puede variar.
            </p>
          )}
        </div>
      </div>

      {/* Gráfico */}
      <div className="rounded-xl border border-border bg-card p-4">
        <h3 className="text-base font-semibold text-foreground mb-4">
          Impacto en Ingresos (Top 5 Bebidas)
        </h3>
        <div className="w-full overflow-x-auto">
          <div style={{ minWidth: "300px" }}>
            <ResponsiveContainer width="100%" height={220}>
              <BarChart data={metricas.topProductos} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" vertical={false} />
                <XAxis
                  dataKey="producto"
                  stroke="hsl(var(--muted-foreground))"
                  fontSize={12}
                  tickFormatter={(val) => (val.length > 12 ? val.substring(0, 12) + "..." : val)}
                />
                <YAxis stroke="hsl(var(--muted-foreground))" fontSize={12} width={60} />
                <Tooltip
                  contentStyle={{
                    backgroundColor: "hsl(var(--card))",
                    borderColor: "hsl(var(--border))",
                    color: "hsl(var(--foreground))",
                    borderRadius: "8px",
                  }}
                  formatter={(value: number) => formatBs(value)}
                />
                <Legend wrapperStyle={{ fontSize: "12px", color: "hsl(var(--muted-foreground))" }} />
                <Bar dataKey="ingresoActual" name="Ingreso Actual" fill="var(--viz-1)" radius={[4, 4, 0, 0]} />
                <Bar dataKey="ingresoProyectado" name="Ingreso Proyectado" fill="var(--viz-2)" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Tabla de Precios (Muestra rápida) */}
      <div className="rounded-xl border border-border bg-card p-4">
        <h3 className="text-base font-semibold text-foreground mb-3">Nuevos Precios Sugeridos</h3>
        <div className="grid gap-2 max-h-48 overflow-y-auto pr-2">
          {productosProcesados.map((p, i) => (
            <div key={i} className="flex justify-between items-center text-sm border-b border-border pb-2 last:border-0">
              <span className="text-foreground truncate pr-2">{p.producto}</span>
              <div className="flex items-center gap-2 shrink-0">
                <span className="text-muted-foreground line-through">{formatBs(p.precioActual)}</span>
                <span className="text-primary font-medium">{formatBs(p.nuevoPrecio)}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Acción */}
      <div className="rounded-xl border border-border bg-card p-4 flex flex-col items-center text-center">
        <button
          onClick={aplicarPrecios}
          className="bg-primary text-primary-foreground px-6 py-2 rounded-lg font-medium hover:opacity-90 transition-opacity w-full sm:w-auto"
        >
          Proponer Nuevos Precios
        </button>
        <p className="text-xs text-muted-foreground mt-2">
          Vas a poder revisarlo antes de que se aplique.
        </p>
      </div>
    </div>
  );
}

